SELECT AVG(CAST(metric_0001 AS DOUBLE)) AS avg_metric_0001, AVG(CAST(metric_0112 AS DOUBLE)) AS avg_metric_0112, AVG(CAST(metric_0223 AS DOUBLE)) AS avg_metric_0223, AVG(CAST(metric_0334 AS DOUBLE)) AS avg_metric_0334, AVG(CAST(metric_0445 AS DOUBLE)) AS avg_metric_0445, AVG(CAST(metric_0556 AS DOUBLE)) AS avg_metric_0556, AVG(CAST(metric_0667 AS DOUBLE)) AS avg_metric_0667, AVG(CAST(metric_0778 AS DOUBLE)) AS avg_metric_0778, AVG(CAST(metric_0889 AS DOUBLE)) AS avg_metric_0889, AVG(CAST(metric_1000 AS DOUBLE)) AS avg_metric_1000 FROM wide1000 WHERE time >= '2024-12-22' AND time < '2025-01-01'
